import{_ as e}from"./chunks/introduction.B_4Vv96H.js";import{_ as o,o as n,c as i,a5 as r}from"./chunks/framework.DGp912Ge.js";const p=JSON.parse('{"title":"3. GUI Introduction","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/common/gui-introduction.md","filePath":"guides/common/gui-introduction.md","lastUpdated":1785806767000}'),a={name:"guides/common/gui-introduction.md"};function s(d,t,l,c,g,h){return n(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-gui-introduction" tabindex="-1">3. GUI Introduction <a class="header-anchor" href="#_3-gui-introduction" aria-label="Permalink to &quot;3. GUI Introduction&quot;">​</a></h1><p><strong>Goal:</strong> Get familiar with the RBQGUI screen layout and key buttons before sending motion commands.</p><p><strong>Prerequisites:</strong> <a href="/RBQ/guides/common/controller-wifi-connect.html">Controller &amp; Wi-Fi Connection</a> must be completed — RBQGUI should be linked to the robot.</p><h2 id="main-screen" tabindex="-1">Main Screen <a class="header-anchor" href="#main-screen" aria-label="Permalink to &quot;Main Screen&quot;">​</a></h2><p>After Auto Start completes, the RBQGUI main screen looks like this:</p><figure style="margin-top:0;text-align:center;"><img src="'+e+'" alt="RBQGUI main screen" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;">&lt;RBQGUI main screen&gt;</figcaption></figure><p>RBQGUI provides three core capabilities:</p><ul><li><strong>Connection</strong> — Communicates with the robot on the same Wi-Fi network.</li><li><strong>Control</strong> — Selects gait modes (sit, stance, walk, stair, docking, RL) and drives the robot via the joystick.</li><li><strong>Monitoring</strong> — Shows battery, sensor, and connection status on screen.</li></ul><h2 id="button-reference-1–9" tabindex="-1">Button Reference (1–9) <a class="header-anchor" href="#button-reference-1–9" aria-label="Permalink to &quot;Button Reference (1–9)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">No.</th><th>Function</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><strong>Sit</strong> — keep the robot in a sitting pose</td></tr><tr><td style="text-align:right;">2</td><td><strong>Stance</strong> — stand up to the default pose</td></tr><tr><td style="text-align:right;">3</td><td><strong>Walk</strong> — walk (forward/back, strafe, turn)</td></tr><tr><td style="text-align:right;">4</td><td><strong>Stair</strong> — gait suited for stairs</td></tr><tr><td style="text-align:right;">5</td><td><strong>Docking</strong> — align to the charging dock</td></tr><tr><td style="text-align:right;">6</td><td><strong>RL (Vision Trot)</strong> — vision-based RL walking</td></tr><tr><td style="text-align:right;">7</td><td><strong>Walking Parameter Setting</strong> — tune speed, body height, foot lift</td></tr><tr><td style="text-align:right;">8</td><td><strong>3D Virtual View</strong> — switch to the 3D virtual view</td></tr><tr><td style="text-align:right;">9</td><td><strong>Camera View</strong> — switch to the live camera view</td></tr></tbody></table><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>When the robot posture or the app view changes, the corresponding button turns orange.</p></div></div><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Now that you know what each button does, try the basic motion commands:</p><p><strong><a href="/RBQ/guides/common/basic-motion-command.html">→ 4. Basic Motion Command</a></strong></p>',14)])])}const b=o(a,[["render",s]]);export{p as __pageData,b as default};
